with cleaned as (select id, session_id, event_type, page, event_time, duration_sec, round(duration_sec, 1) as duration_sec_rounded, to_date(event_time) as event_time_date from web_events where page is not null) select id, event_type, duration_sec_rounded, ntile(5) over w_part as duration_sec_bucket, row_number() over (partition by page order by event_time, id) as seq_no, ntile(10) over w_part_2 as duration_sec_bucket_2, dense_rank() over (partition by session_id, event_type order by duration_sec nulls last) as duration_sec_dense_rank from cleaned where session_id in (4, 5, 16, 25) window w_part as (order by duration_sec, id), w_part_2 as (partition by session_id order by duration_sec, id);
